1	// SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	//
3	// SPDX-License-Identifier: MIT
4	
5	//
6	// Shared FFI marshalling for every cutile-rs op (the Rust "unpacker").
7	//
8	// Each op's ffi.rs used to hand-unpack ptr + dims + strides + elem_size + dtype
9	// for every tensor and then `mem::forget` each borrowed wrapper. This centralizes
10	// that: ops receive `*const TensorDesc` and call `borrow_tensor::<E>(desc)`.
11	// Mirrors how tilecpp centralizes arg packing in `make_kernel_args`, but on the
12	// Rust side. Keep `TensorDesc` in sync with the cffi typedef in
13	// backend/cutile_rs/utils.py (`_TENSORDESC_CDEF`) and the Python packer
14	// `make_tensor_desc`.
15	
16	use core::mem::ManuallyDrop;
17	use cutile::prelude::*;
18	
19	/// Max tensor rank carried by a [`TensorDesc`]. Bump (here + in the Python cdef)
20	/// if an op needs higher-rank tensors.
21	pub const MAX_DIMS: usize = 5;
22	
23	/// C-ABI view of a device tensor borrowed from PyTorch. `#[repr(C)]` layout MUST
24	/// match `_TENSORDESC_CDEF` in backend/cutile_rs/utils.py. Strides are in ELEMENTS
25	/// (not bytes); `shape`/`strides` entries beyond `ndim` are ignored.
26	#[repr(C)]
27	pub struct TensorDesc {
28	    pub ptr: u64,
29	    pub ndim: i32,
30	    pub shape: [i64; MAX_DIMS],
31	    pub strides: [i64; MAX_DIMS],
32	    /// dtype code: 0 = f32, 1 = f16, 2 = bf16, 3 = i32, 4 = i64, 5 = f8e5m2.
33	    pub dtype: i32,
34	}
35	
36	impl TensorDesc {
37	    /// Logical extent of dimension `i` as i32 (cutile's `from_raw_parts` wants i32).
38	    pub fn dim(&self, i: usize) -> i32 {
39	        self.shape[i] as i32
40	    }
41	
42	    fn shape_i32(&self) -> Vec<i32> {
43	        (0..self.ndim as usize)
44	            .map(|i| self.shape[i] as i32)
45	            .collect()
46	    }
47	
48	    fn strides_i32(&self) -> Vec<i32> {
49	        (0..self.ndim as usize)
50	            .map(|i| self.strides[i] as i32)
51	            .collect()
52	    }
53	
54	    fn nelem(&self) -> usize {
55	        (0..self.ndim as usize)
56	            .map(|i| self.shape[i] as usize)
57	            .product()
58	    }
59	
60	    /// Total byte length of the (contiguous) allocation this view spans.
61	    pub fn nbytes(&self) -> usize {
62	        self.nelem() * dtype_elem_size(self.dtype)
63	    }
64	}
65	
66	/// dtype code -> cutile type-name string used in `.generics(...)`. `None` if unknown.
67	/// Codes 3 (i32) / 4 (i64) are integer tensors (index / descriptor-table
68	/// entries), never element-type generics; included for completeness.
69	pub fn dtype_str(code: i32) -> Option<&'static str> {
70	    match code {
71	        0 => Some("f32"),
72	        1 => Some("f16"),
73	        2 => Some("bf16"),
74	        3 => Some("i32"),
75	        4 => Some("i64"),
76	        5 => Some("f8e5m2"),
77	        _ => None,
78	    }
79	}
80	
81	/// dtype code -> element size in bytes. `0` if unknown.
82	pub fn dtype_elem_size(code: i32) -> usize {
83	    match code {
84	        0 | 3 => 4,
85	        1 | 2 => 2,
86	        4 => 8,
87	        5 => 1,
88	        _ => 0,
89	    }
90	}
91	
92	/// `CAST_TF32` generic value: 1 iff the dtype is f32, else 0.
93	pub fn cast_tf32(code: i32) -> i32 {
94	    i32::from(code == 0)
95	}
96	
97	/// C-ABI return codes shared by every op's `ffi.rs`. `0` = success; negatives are
98	/// errors. Keep in sync with `_RC_MESSAGES` in backend/cutile_rs/utils.py.
99	///
100	/// NOTE: `-1` is intentionally NOT a return code — it is the "auto / compiler
101	/// default" sentinel for the `num_cta_in_cga` / `occupancy` inputs
102	/// (`_AUTO_COMPILE_OPTION` in the Python wrappers), so it must not be overloaded.
103	pub mod rc {
104	    /// Kernel launched and synced successfully.
105	    pub const OK: i32 = 0;
106	    /// A `TensorDesc.dtype` code has no cutile element type (see `dtype_str`).
107	    pub const UNSUPPORTED_DTYPE: i32 = -2;
108	    /// The kernel launch / stream sync returned an error.
109	    pub const LAUNCH_FAILED: i32 = -3;
110	    /// `Device::new(device_id)` failed.
111	    pub const DEVICE_INIT_FAILED: i32 = -4;
112	    /// A required `*const TensorDesc` argument was null.
113	    pub const NULL_PTR: i32 = -5;
114	    /// A scalar / shape / launch parameter was invalid (e.g. a non-positive
115	    /// dimension, block, or grid size, or an out-of-range variant selector).
116	    pub const INVALID_ARGS: i32 = -6;
117	}
118	
119	/// Human-readable message for an FFI return code (diagnostics / `eprintln!`).
120	pub fn rc_message(code: i32) -> &'static str {
121	    match code {
122	        rc::OK => "ok",
123	        rc::UNSUPPORTED_DTYPE => "unsupported dtype",
124	        rc::LAUNCH_FAILED => "kernel launch failed",
125	        rc::DEVICE_INIT_FAILED => "device init failed",
126	        rc::NULL_PTR => "null tensor pointer",
127	        rc::INVALID_ARGS => "invalid arguments",
128	        _ => "unknown error",
129	    }
130	}
131	
132	/// Null-check each `*const TensorDesc` (returning `rc::NULL_PTR` from the calling
133	/// FFI fn on any null) then deref them all to `&TensorDesc` in one `unsafe` block.
134	/// Replaces the per-op `if a.is_null() || ... { return -5; } let (..) = unsafe {..};`
135	/// boilerplate. Every op passes >= 2 descriptors, so this always yields a tuple.
136	#[macro_export]
137	macro_rules! deref_descs {
138	    ($($p:ident),+ $(,)?) => {{
139	        $( if $p.is_null() { return $crate::ffi_util::rc::NULL_PTR; } )+
140	        unsafe { ($(&*$p),+) }
141	    }};
142	}
143	
144	/// Resolve a `TensorDesc`'s dtype code to its cutile element-type string, or
145	/// `return rc::UNSUPPORTED_DTYPE` from the calling FFI fn. Evaluates to `&'static str`.
146	#[macro_export]
147	macro_rules! resolve_dtype {
148	    ($d:expr) => {
149	        match $crate::ffi_util::dtype_str($d.dtype) {
150	            Some(s) => s,
151	            None => return $crate::ffi_util::rc::UNSUPPORTED_DTYPE,
152	        }
153	    };
154	}
155	
156	/// Bind `$dev` to a cuda-core `Device` for `$device_id` (must be >= 0; a
157	/// negative id is rejected rather than coerced to GPU 0) and `$strm` to a
158	/// *borrowed* `Stream` over the caller's raw CUDA stream, in the caller's
159	/// scope. On an invalid id or device-init failure it `return rc::DEVICE_INIT_FAILED`s
160	/// from the calling FFI fn. Replaces the per-op device+stream setup boilerplate.
161	///
162	/// Resolves `Device` / `Stream` / `c_void` at the call site, so the ffi.rs must
163	/// have `use cuda_core::{Device, Stream};` and `use core::ffi::c_void;` in scope
164	/// (every op already does). The borrow ties `$strm` to `$dev`, so both are bound
165	/// in the caller (not returned as a tuple).
166	#[macro_export]
167	macro_rules! setup_device_stream {
168	    ($dev:ident, $strm:ident, $device_id:expr, $raw_stream:expr) => {
169	        if ($device_id) < 0 {
170	            eprintln!("cutile-rs: invalid device id: {}", $device_id);
171	            return $crate::ffi_util::rc::DEVICE_INIT_FAILED;
172	        }
173	        let $dev = match Device::new(($device_id) as usize) {
174	            Ok(d) => d,
175	            Err(e) => {
176	                eprintln!("cutile-rs: Device::new failed: {e:?}");
177	                return $crate::ffi_util::rc::DEVICE_INIT_FAILED;
178	            }
179	        };
180	        let $strm = unsafe { Stream::borrow_raw(($raw_stream) as *mut c_void, &$dev) };
181	    };
182	}
183	
184	/// Dispatch on a dtype string `$dty` to the op-local `$dispatch!(<E>)` macro, one
185	/// arm per supported element type, falling back to `rc::UNSUPPORTED_DTYPE`. The
186	/// arm string is `stringify!($ty)`, which matches `dtype_str` (e.g. `f16`, `bf16`,
187	/// `f8e5m2`). Pass only the dtypes an op actually supports:
188	///   `dispatch_by_dtype!(dty, dispatch, f32, f16, bf16)`         // most ops
189	///   `dispatch_by_dtype!(dty, dispatch, f32, f16, bf16, f8e5m2)` // + fp8 ops
190	#[macro_export]
191	macro_rules! dispatch_by_dtype {
192	    ($dty:expr, $dispatch:ident, $($ty:ident),+ $(,)?) => {
193	        match $dty {
194	            $( stringify!($ty) => $dispatch!($ty), )+
195	            _ => $crate::ffi_util::rc::UNSUPPORTED_DTYPE,
196	        }
197	    };
198	}
199	
200	/// Build a `CompileOptions` from the FFI compile-option ints, applying only
201	/// positive values — `<= 0` means "auto / compiler default" (the
202	/// `_AUTO_COMPILE_OPTION` = -1 sentinel). Evaluates to the `CompileOptions`.
203	/// Resolves `CompileOptions` at the call site (every ffi.rs imports it).
204	#[macro_export]
205	macro_rules! compile_options {
206	    ($occupancy:expr, $num_cta_in_cga:expr) => {{
207	        let mut opts = CompileOptions::default();
208	        if $occupancy > 0 {
209	            opts = opts.occupancy($occupancy);
210	        }
211	        if $num_cta_in_cga > 0 {
212	            opts = opts.num_cta_in_cga($num_cta_in_cga);
213	        }
214	        opts
215	    }};
216	}
217	
218	/// Borrow a PyTorch tensor as a cutile `Tensor<E>` WITHOUT taking ownership.
219	///
220	/// The returned [`ManuallyDrop`] never runs `Tensor::Drop`, so the underlying
221	/// PyTorch device memory is never freed when it goes out of scope — the FFI
222	/// ownership gate, enforced by construction (no explicit `mem::forget` needed).
223	/// Access the tensor via `&*` / `&**`.
224	///
225	/// # Safety
226	/// `d.ptr` must point to a live device allocation of at least `d.nbytes()` bytes,
227	/// holding elements of type `E` laid out per `d.shape`/`d.strides`, and must stay
228	/// valid for the duration of the kernel launch.
229	pub unsafe fn borrow_tensor<E: DType>(d: &TensorDesc) -> ManuallyDrop<Tensor<E>> {
230	    ManuallyDrop::new(unsafe {
231	        Tensor::<E>::from_raw_parts(d.ptr, d.nbytes(), 0, d.shape_i32(), d.strides_i32())
232	    })
233	}
234

